/* Phase C — Smart dispatch and constrained routing (features 31–36, 38, 73). */

create table if not exists public.road_closures(
 id uuid primary key default gen_random_uuid(),name text not null,reason text not null,zone geometry(polygon,4326) not null,
 source text not null default 'coordinator',trust_level text not null default 'confirmed' check(trust_level in('reported','probable','confirmed')),
 active boolean not null default true,starts_at timestamptz not null default now(),expires_at timestamptz,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create index if not exists idx_road_closures_zone on public.road_closures using gist(zone);
alter table public.road_closures enable row level security;
create policy road_closures_auth_read on public.road_closures for select to authenticated using(true);
create policy road_closures_admin_write on public.road_closures for all to authenticated using(private.is_admin()) with check(private.is_admin());
grant select,insert,update,delete on public.road_closures to authenticated;

create or replace function public.admin_create_road_closure(p_name text,p_reason text,p_coordinates jsonb,p_trust_level text default 'confirmed',p_expires_at timestamptz default null)
returns public.road_closures language plpgsql security definer set search_path=public,extensions as $$ declare z public.road_closures;g geometry;begin if not private.is_admin() then raise exception 'Administrator access required';end if;if jsonb_array_length(p_coordinates)<3 then raise exception 'At least three map points are required';end if;
 g:=st_makepolygon(st_makeline(array(select st_setsrid(st_makepoint((x->>1)::float,(x->>0)::float),4326) from jsonb_array_elements(p_coordinates) x union all select st_setsrid(st_makepoint((p_coordinates->0->>1)::float,(p_coordinates->0->>0)::float),4326))));
 if not st_isvalid(g) then raise exception 'Closure polygon is invalid';end if;
 insert into public.road_closures(name,reason,zone,trust_level,expires_at,created_by) values(trim(p_name),trim(p_reason),g,p_trust_level,p_expires_at,auth.uid()) returning * into z;
 insert into public.alerts(type,severity,message,dedup_key) values('road_closure','high','Road closure added: '||z.name,'closure-'||z.id);
 return z;end $$;

create or replace function public.list_active_road_closures() returns table(id uuid,name text,reason text,geojson jsonb,source text,trust_level text,expires_at timestamptz) language sql security invoker set search_path=public,extensions as $$ select r.id,r.name,r.reason,st_asgeojson(r.zone)::jsonb,r.source,r.trust_level,r.expires_at from public.road_closures r where r.active and (r.expires_at is null or r.expires_at>now());$$;

create or replace function public.recommend_teams_v2(p_incident_id uuid)
returns table(team_id uuid,team_name text,team_code text,current_status public.team_status,distance_km double precision,capability_match integer,required_capabilities text[],equipment text[],missing_equipment text[],capacity integer,capacity_gap integer,eligible boolean,recommendation_reason text)
language plpgsql security invoker set search_path=public,extensions as $$ declare inc public.incidents;req text[];eq text[];begin select * into inc from public.incidents where id=p_incident_id;if not found then raise exception 'Incident not found';end if;
 req:=case inc.type when 'flood' then array['flood rescue','water rescue'] when 'fire' then array['fire response'] when 'medical_emergency' then array['medical'] when 'heatwave' then array['medical'] else array['general rescue'] end;
 eq:=case inc.type when 'flood' then array['boat','life jackets'] when 'fire' then array['fire extinguisher','breathing apparatus'] when 'medical_emergency' then array['medical kit'] when 'heatwave' then array['water','medical kit'] else array[]::text[] end;
 return query select t.id,t.name,t.team_code,t.status,round((st_distance(t.location,inc.location)/1000.0)::numeric,1)::float8,(select count(*)::int from unnest(req) q where exists(select 1 from unnest(t.capabilities) c where lower(c)=lower(q))),req,t.equipment,array(select e from unnest(eq)e where not exists(select 1 from unnest(t.equipment)te where lower(te)=lower(e))),t.capacity,greatest(0,inc.people_affected-t.capacity),(t.status='available' and t.capacity>0),format('%s/%s capabilities; %s km straight-line; capacity %s for %s people%s',(select count(*) from unnest(req)q where exists(select 1 from unnest(t.capabilities)c where lower(c)=lower(q))),cardinality(req),round((st_distance(t.location,inc.location)/1000.0)::numeric,1),t.capacity,inc.people_affected,case when t.status<>'available' then '; unavailable' when t.capacity<inc.people_affected then '; capacity shortfall' when exists(select 1 from unnest(eq)e where not exists(select 1 from unnest(t.equipment)te where lower(te)=lower(e))) then '; equipment gaps shown' else '' end)
 from public.rescue_teams t where t.location is not null order by (t.status='available') desc,(select count(*) from unnest(req)q where exists(select 1 from unnest(t.capabilities)c where lower(c)=lower(q))) desc,(cardinality(array(select e from unnest(eq)e where not exists(select 1 from unnest(t.equipment)te where lower(te)=lower(e))))) asc,st_distance(t.location,inc.location);end $$;

create table if not exists public.dispatch_plans(
 id uuid primary key default gen_random_uuid(),status text not null default 'draft' check(status in('draft','approved','superseded')),trigger_reason text not null,plan jsonb not null,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),approved_at timestamptz
);
alter table public.dispatch_plans enable row level security;create policy dispatch_plans_admin on public.dispatch_plans for all to authenticated using(private.is_admin()) with check(private.is_admin());grant select,insert,update on public.dispatch_plans to authenticated;

create or replace function public.admin_generate_dispatch_plan(p_reason text default 'Coordinator requested plan') returns uuid language plpgsql security definer set search_path=public,extensions as $$ declare pid uuid;body jsonb;begin if not private.is_admin() then raise exception 'Administrator access required';end if;
 with ranked as(select i.*,row_number()over(order by i.priority_score desc,i.created_at) rn from public.incidents i where i.status in('reported','verified') and i.primary_incident_id is null), candidates as(select i.id incident_id,i.report_code,i.priority_level,i.priority_score,i.people_affected,t.id team_id,t.name team_name,round((st_distance(t.location,i.location)/1000)::numeric,1) distance_km,row_number()over(partition by i.id order by (t.capacity>=i.people_affected)desc,st_distance(t.location,i.location)) choice,row_number()over(partition by t.id order by i.priority_score desc,i.created_at) team_use from ranked i left join public.rescue_teams t on t.status='available' and t.location is not null)
 select coalesce(jsonb_agg(jsonb_build_object('incident_id',incident_id,'report_code',report_code,'priority',priority_level,'score',priority_score,'team_id',case when choice=1 and team_use=1 then team_id end,'team_name',case when choice=1 and team_use=1 then team_name end,'straight_line_km',case when choice=1 and team_use=1 then distance_km end,'reason',case when choice=1 and team_use=1 then 'Highest-priority incident matched to the nearest unused available team; capacity fit was preferred' end,'gap',case when team_id is null then 'No available team' when not(choice=1 and team_use=1) then 'Team capacity conflict — manual coordination required' else null end)order by priority_score desc),'[]'::jsonb) into body from candidates where choice=1 or team_id is null;
 update public.dispatch_plans set status='superseded' where status='draft';insert into public.dispatch_plans(trigger_reason,plan,created_by)values(trim(p_reason),body,auth.uid())returning id into pid;return pid;end $$;

create or replace function private.replan_road_closure() returns trigger language plpgsql security definer set search_path=public as $$begin perform public.admin_generate_dispatch_plan('Road closure added: '||new.name);return new;end$$;
drop trigger if exists trg_road_closure_replan on public.road_closures;create trigger trg_road_closure_replan after insert on public.road_closures for each row execute function private.replan_road_closure();

create or replace function public.admin_approve_dispatch_plan(p_plan_id uuid) returns integer language plpgsql security definer set search_path=public as $$ declare item jsonb;n int:=0;begin if not private.is_admin() then raise exception 'Administrator access required';end if;for item in select * from jsonb_array_elements((select plan from public.dispatch_plans where id=p_plan_id and status='draft')) loop if item->>'team_id' is not null and exists(select 1 from public.rescue_teams where id=(item->>'team_id')::uuid and status='available') and exists(select 1 from public.incidents where id=(item->>'incident_id')::uuid and status in('reported','verified')) then perform public.create_assignment((item->>'incident_id')::uuid,(item->>'team_id')::uuid,'{}','approved dispatch plan');n:=n+1;end if;end loop;update public.dispatch_plans set status='approved',approved_at=now()where id=p_plan_id;return n;end $$;

create or replace function private.replan_unavailable_team() returns trigger language plpgsql security definer set search_path=public as $$ begin if old.status is distinct from new.status and new.status in('unavailable','offline') then perform public.admin_generate_dispatch_plan('Automatic replan: team '||new.name||' became '||new.status);insert into public.alerts(type,severity,message,dedup_key)values('team_unavailable','high',new.name||' became '||new.status||'; a replacement draft plan was generated','team-unavailable-'||new.id||'-'||extract(epoch from now())::bigint);end if;return new;end $$;
drop trigger if exists trg_team_replan on public.rescue_teams;create trigger trg_team_replan after update of status on public.rescue_teams for each row execute function private.replan_unavailable_team();

create table if not exists public.resource_movements(id uuid primary key default gen_random_uuid(),resource_id uuid not null references public.resources(id),assignment_id uuid references public.assignments(id),movement_type text not null check(movement_type in('received','reserved','released','used','lost','transferred','adjusted')),quantity integer not null check(quantity>0),source_location text,destination_location text,reason text not null,actor_id uuid references public.profiles(id),created_at timestamptz not null default now());
create index if not exists idx_resource_movements_resource on public.resource_movements(resource_id,created_at desc);alter table public.resource_movements enable row level security;create policy resource_movements_admin on public.resource_movements for all to authenticated using(private.is_admin()) with check(private.is_admin());grant select,insert on public.resource_movements to authenticated;
create or replace function private.log_resource_stock_movement()returns trigger language plpgsql security definer set search_path=public as $$ declare d int;rd int;kind text;qty int;why text;begin d:=new.quantity_available-old.quantity_available;rd:=new.quantity_reserved-old.quantity_reserved;if d=0 and rd=0 then return new;end if;
 kind:=case when rd>0 and d<0 then 'reserved' when rd<0 and d>0 then 'released' when rd<0 and d=0 then 'used' when d>0 then 'received' else 'used'end;qty:=greatest(abs(d),abs(rd));why:=coalesce(nullif(current_setting('resqnet.reason',true),''),case kind when 'reserved' then 'Reserved for rescue assignment' when 'released' then 'Released from rescue assignment' when 'used' then 'Used or removed from inventory' else 'Inventory received' end);
 insert into public.resource_movements(resource_id,movement_type,quantity,source_location,destination_location,reason,actor_id)values(new.id,kind,qty,nullif(current_setting('resqnet.source_location',true),''),nullif(current_setting('resqnet.destination_location',true),''),why,auth.uid());return new;end $$;
drop trigger if exists trg_resource_stock_movement on public.resources;create trigger trg_resource_stock_movement after update of quantity_available on public.resources for each row execute function private.log_resource_stock_movement();
create or replace function public.admin_record_resource_movement(p_resource_id uuid,p_type text,p_quantity integer,p_source text,p_destination text,p_reason text)returns uuid language plpgsql security definer set search_path=public as $$declare mid uuid;begin if not private.is_admin()then raise exception 'Administrator access required';end if;if p_quantity<=0 or p_type not in('received','used','lost','transferred','adjusted')then raise exception 'Invalid movement';end if;insert into public.resource_movements(resource_id,movement_type,quantity,source_location,destination_location,reason,actor_id)values(p_resource_id,p_type,p_quantity,nullif(trim(p_source),''),nullif(trim(p_destination),''),trim(p_reason),auth.uid())returning id into mid;return mid;end $$;

create or replace function public.area_response_fairness()returns table(area_id uuid,area_name text,vulnerability_index numeric,population integer,open_incidents bigint,unanswered_incidents bigint,median_response_minutes numeric,nearest_available_team_km numeric,reports_per_1000 numeric,is_demo boolean)language sql security invoker set search_path=public,extensions as $$ select a.id,a.name,a.vulnerability_index,a.population,count(i.id)filter(where i.status not in('resolved','cancelled')),count(i.id)filter(where i.status in('reported','verified')and i.created_at<now()-interval '30 minutes'),round(percentile_cont(.5)within group(order by extract(epoch from(coalesce(x.assigned_at,now())-i.created_at))/60)::numeric,1),round((select min(st_distance(t.location,st_centroid(a.boundary)::geography)/1000)from public.rescue_teams t where t.status='available'and t.location is not null)::numeric,1),round((count(i.id)filter(where i.created_at>now()-interval '24 hours')*1000.0/greatest(a.population,1))::numeric,2),a.is_demo from public.areas a left join public.incidents i on i.area_id=a.id left join lateral(select min(assigned_at)assigned_at from public.assignments where incident_id=i.id)x on true group by a.id;$$;

grant execute on function public.admin_create_road_closure(text,text,jsonb,text,timestamptz),public.list_active_road_closures(),public.recommend_teams_v2(uuid),public.admin_generate_dispatch_plan(text),public.admin_approve_dispatch_plan(uuid),public.admin_record_resource_movement(uuid,text,integer,text,text,text),public.area_response_fairness() to authenticated;
do $$begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime'and schemaname='public'and tablename='road_closures')then alter publication supabase_realtime add table public.road_closures;end if;if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime'and schemaname='public'and tablename='dispatch_plans')then alter publication supabase_realtime add table public.dispatch_plans;end if;end $$;
